import { View, Text, Pressable, Animated, StyleSheet } from "react-native";
import { useRef } from "react";
import { registerRootComponent } from "expo";

function App() {
  const h = useRef(new Animated.Value(0)).current;
  const open = () => {
    Animated.timing(h, { toValue: 140, duration: 300 }).start();
  };
  return (
    <View style={styles.s}>
      <Pressable nativeID="open" style={styles.head} onPress={open}><Text style={styles.headText}>Дэлгэрэнгүй ▾</Text></Pressable>
      <Animated.View nativeID="panel" style={[styles.panel, { height: h }]}>
        <Text style={styles.body}>Энэ бараа 24 сарын баталгаатай, үнэгүй хүргэлттэй.</Text>
      </Animated.View>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, justifyContent: "center" },
  head: { backgroundColor: "#2563eb", padding: 16, borderRadius: 12 }, headText: { color: "#fff", fontWeight: "bold" },
  panel: { overflow: "hidden", backgroundColor: "#eff6ff", borderRadius: 12 }, body: { padding: 16, color: "#1e3a8a" },
});

registerRootComponent(App);
